inline std::string get_dashboard_html(std::string_view version) {
return webui::start("Frame controller","remote")+R"DASHBOARD(
<style>
.remote-layout{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(300px,1fr);gap:22px;align-items:start}.preview-card{padding:13px;overflow:hidden}.preview-top{display:flex;justify-content:space-between;align-items:center;padding:10px 10px 18px;gap:10px}.preview-top .eyebrow{margin:0}.preview-stage{position:relative;aspect-ratio:16/10;border-radius:15px;background:#080e12;overflow:hidden;display:grid;place-items:center}.preview-image{width:100%;height:100%;object-fit:contain}.preview-loading{position:absolute;inset:auto 15px 15px;background:#10191ee6;color:#d8eeeb;border-radius:9px;padding:7px 11px;font-size:12px}.media-info{padding:20px 11px 16px;min-width:0}.media-title{font-size:18px;font-weight:700;line-height:1.4;overflow-wrap:anywhere;user-select:text}.media-meta{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--muted);margin-top:10px}.media-meta>span:last-child{margin-left:auto}.progress-track{height:3px;border-radius:5px;background:var(--line);margin-top:18px;overflow:hidden}.progress-fill{height:100%;background:var(--accent);width:0;transition:width .4s linear}.playback-controls{display:grid;grid-template-columns:1fr 1.65fr 1fr;gap:10px;margin:0 10px 14px}.playback-controls button{min-height:54px;font-size:13px}.secondary-controls{display:flex;gap:10px;flex-wrap:wrap;padding:0 10px 10px}.secondary-controls button{font-size:12px;flex:1;white-space:nowrap}.secondary-controls button[aria-pressed=true]{color:var(--accent);border-color:var(--accent)}.preview-note{padding:0 10px 9px;color:var(--muted);font-size:11px}.health-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px 10px}.health-value{font-size:16px;font-weight:650;letter-spacing:-.2px;overflow-wrap:anywhere}.health-label{font-size:10px;text-transform:uppercase;letter-spacing:.8px;color:var(--muted);margin-bottom:5px}.mqtt-status{border-top:1px solid var(--line);margin-top:20px;padding-top:16px;display:flex;justify-content:space-between;gap:12px;font-size:12px}.mqtt-status code{font-size:10px;color:var(--muted)}.home-number{font-size:35px;font-weight:750;letter-spacing:-1px;margin:6px 0}.home-number span{font-size:15px;color:var(--muted);letter-spacing:0;font-weight:400}.home-summary p{font-size:13px;margin:12px 0 18px}.home-summary .button{width:100%}.lan-card p{font-size:12px;margin:9px 0 13px}.lan-row{display:flex;gap:8px}.lan-row input{font-size:12px!important;padding:9px!important}.lan-row button{font-size:12px;padding:9px 12px}.frame-actions{display:flex;gap:10px;border-top:1px solid var(--line);padding-top:18px;margin-top:18px}.frame-actions button{flex:1;font-size:12px}.log-toolbar{display:flex;align-items:center;gap:14px;margin-bottom:18px;flex-wrap:wrap}.log-toolbar input[type=search]{flex:1;min-width:180px}.log-toolbar .check-label{font-size:12px}.log-console{margin:0;min-height:360px;height:60dvh;max-height:800px;overflow:auto;padding:20px;background:var(--bg);border:1px solid var(--line);border-radius:14px;color:var(--muted);font:12px/1.8 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;user-select:text}.log-status{display:flex;justify-content:space-between;gap:10px;margin-top:13px;font-size:11px;color:var(--muted)}.heading-actions{display:flex;gap:8px;flex-shrink:0}.keyboard-hint{font-size:11px;color:var(--muted);text-align:center;margin-top:15px}.summary-progress{width:100%;height:5px;accent-color:var(--accent);border:0;border-radius:5px;overflow:hidden}.summary-progress::-webkit-progress-bar{background:var(--line)}.summary-progress::-webkit-progress-value{background:var(--accent)}.summary-progress::-moz-progress-bar{background:var(--accent)}
@media(max-width:1000px){.remote-layout{grid-template-columns:minmax(0,1.5fr) minmax(280px,1fr)}.health-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:760px){.remote-layout{grid-template-columns:minmax(0,1fr);gap:16px}.preview-card{padding:9px}.preview-stage{aspect-ratio:16/10;border-radius:13px}.page-heading p{display:none}.page-heading{flex-wrap:wrap}.heading-actions{width:100%}.heading-actions .button{flex:1}.media-title{font-size:16px}.playback-controls{gap:8px;margin-left:5px;margin-right:5px}.playback-controls button{font-size:12px;padding:10px 8px;min-height:54px}.secondary-controls{padding-left:5px;padding-right:5px;gap:8px}.secondary-controls button{font-size:11px;padding:9px 7px}.health-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.keyboard-hint{display:none}.log-toolbar{gap:9px}.log-toolbar input[type=search]{flex-basis:100%}.log-toolbar .check-label{flex:1}.log-console{padding:13px;font-size:11px}.preview-top{padding:8px 8px 14px}.preview-top .badge{font-size:10px}.media-info{padding:15px 7px}.lan-row{flex-wrap:wrap}.lan-row input{flex-basis:100%}.lan-row button{width:100%}}
</style>
<div id="controller-error" class="notice" role="alert" hidden></div>
<section id="tab-remote-content">
<div class="page-heading"><div><div class="eyebrow">A window into home</div><h1>Your frame, from here.</h1><p>Keep the memories moving. Take care of the little things.</p></div><div class="heading-actions"><a class="button quiet" href="/chores">People &amp; chores</a></div></div>
<div class="remote-layout"><div>
<section class="card preview-card" aria-label="Current media and playback"><div class="preview-top"><span class="eyebrow">On your frame</span><span id="playback-state" class="badge">Connecting</span></div><div class="preview-stage"><img id="preview" class="preview-image" src="/api/preview" alt="Current media preview"><span id="loading" class="preview-loading">Loading preview…</span></div><div class="media-info"><div id="media-title" class="media-title">Connecting to your frame…</div><div class="media-meta"><span id="media-type" class="badge">Photo</span><span id="media-progress">—</span><span id="media-timer">—</span></div><div class="progress-track" aria-hidden="true"><div id="media-progress-fill" class="progress-fill"></div></div></div>
<div class="playback-controls"><button id="btn-prev" aria-label="Previous item"><svg class="icon" aria-hidden="true"><use href="#i-prev"/></svg><span>Previous</span></button><button id="btn-pause" class="primary"><span id="icon-pause" aria-hidden="true">Ⅱ</span><span id="txt-pause">Pause</span></button><button id="btn-next" aria-label="Next item"><span>Next</span><svg class="icon" aria-hidden="true"><use href="#i-next"/></svg></button></div>
<div class="secondary-controls"><button id="btn-shuffle" class="quiet" aria-pressed="false">Shuffle <span id="lbl-shuffle">off</span></button><button id="refresh-preview" class="quiet">Refresh preview</button><button id="capture-frame" class="quiet"><svg class="icon" aria-hidden="true"><use href="#i-camera"/></svg>Save frame image</button></div><p class="preview-note">Media preview · Save a frame image to include panels and the news ticker.</p></section><p class="keyboard-hint">Keyboard: Space to pause · ← previous · → next</p>
</div><aside class="stack">
<section class="card home-summary"><div class="card-heading"><div><div class="eyebrow">A little teamwork</div><h2>Today at home</h2></div><svg class="icon" aria-hidden="true" style="color:var(--accent)"><use href="#i-check"/></svg></div><div id="chore-summary-number" class="home-number">—</div><progress id="chore-summary-progress" class="summary-progress" max="1" value="0" aria-label="Today's chore completion"></progress><p id="chore-summary-text">Loading your household…</p><a class="button" href="/chores">Open the chore board <span aria-hidden="true">↗</span></a></section>
<section class="card"><div class="card-heading"><div><div class="eyebrow">Behind the frame</div><h2>Device overview</h2></div><span id="device-state" class="badge">—</span></div><div class="health-grid"><div><div class="health-label">Uptime</div><div id="stat-uptime" class="health-value">—</div></div><div><div class="health-label">Temperature</div><div id="stat-temp" class="health-value">—</div></div><div><div class="health-label">Memory</div><div id="stat-mem" class="health-value">—</div></div><div><div class="health-label">Disk used</div><div id="stat-disk" class="health-value">—</div></div><div><div class="health-label">Media cache</div><div id="stat-db" class="health-value">—</div></div><div><div class="health-label">Playlist</div><div id="stat-queue" class="health-value">—</div></div></div><div class="mqtt-status"><span>MQTT <strong id="stat-mqtt-status">—</strong></span><code id="stat-mqtt-broker"></code></div><div class="frame-actions"><button id="btn-screen" class="quiet" aria-pressed="false">Screen <strong id="lbl-screen">on</strong></button><button id="restart-frame" class="quiet danger">Restart frame</button></div></section>
<section class="card lan-card"><h2>On your home network</h2><p>Use this exact address, including <strong id="lan-protocol">http://</strong>, on a device connected to your home Wi-Fi.</p><div class="lan-row"><label class="sr-only" for="lan-address">LAN controller address</label><input id="lan-address" readonly type="text" spellcheck="false"><button id="copy-address" class="quiet">Copy address</button></div></section>
</aside></div></section>
<section id="tab-logs-content" hidden><div class="page-heading"><div><div class="eyebrow">A closer look</div><h1>Frame activity</h1><p>Recent diagnostics, with a quick filter when you need it.</p></div><button id="download-logs" class="quiet">Download logs</button></div><section class="card"><div class="log-toolbar"><label class="sr-only" for="log-search">Filter log lines</label><input id="log-search" type="search" placeholder="Filter recent log lines…"><label class="check-label"><input id="live-logs" type="checkbox" checked>Live updates</label><label class="check-label"><input id="follow-logs" type="checkbox" checked>Follow latest</label><button id="refresh-logs" class="quiet">Refresh</button></div><div id="log-error" class="notice" role="alert" hidden></div><pre id="log-console" class="log-console" aria-label="Frame log output" tabindex="0">Loading recent activity…</pre><div class="log-status"><span id="log-lines">Recent frame logs</span><span id="log-updated">Waiting for the frame</span></div></section></section>
<script>
'use strict';
(()=>{
 const {$,request,toast}=FrameUI;let currentTab='remote',lastFilename=null,lastMediaKey=null,lastPaused=null,statusBusy=false,logBusy=false,summaryBusy=false,logs='',lastSummary=0;
 function error(message){$('controller-error').textContent=message||'';$('controller-error').hidden=!message;}
 function refreshPreview(){const image=$('preview');$('loading').hidden=false;$('loading').textContent='Updating preview…';image.src='/api/preview?t='+Date.now();}
 $('preview').addEventListener('load',()=>$('loading').hidden=true);$('preview').addEventListener('error',()=>{$('loading').hidden=false;$('loading').textContent='Preview unavailable · try Refresh preview';});if($('preview').complete&&$('preview').naturalWidth)$('loading').hidden=true;
 function switchTab(){if(location.hash==='#settings'){location.replace('/config');return;}currentTab=location.hash==='#logs'?'logs':'remote';$('tab-remote-content').hidden=currentTab!=='remote';$('tab-logs-content').hidden=currentTab!=='logs';for(const a of document.querySelectorAll('.nav-link')){if(a.dataset.page===currentTab)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}if(currentTab==='logs')fetchLogs();else {fetchStatus();if(lastFilename!==null)refreshPreview();}document.title=(currentTab==='logs'?'Frame activity':'Frame controller')+' · piTrove';}
 async function fetchStatus(){if(statusBusy||document.hidden)return;statusBusy=true;try{const s=await request('/api/status',{protected:false});FrameUI.connection(true);$('device-state').textContent='Online';
  const mediaKey=JSON.stringify([s.index,s.filename,s.is_video]);if(currentTab==='remote'&&(lastMediaKey!==mediaKey||lastPaused!==s.paused)){refreshPreview();}lastFilename=s.filename;lastMediaKey=mediaKey;lastPaused=s.paused;
  $('media-title').textContent=s.total?s.filename:'Your playlist is empty';$('media-title').title=s.filename;$('media-progress').textContent=s.total?(s.index+1)+' / '+s.total:'0 items';$('media-type').textContent=s.is_video?'Video':'Photo';$('media-timer').textContent=s.is_video?'Video playback':Math.max(0,Math.round(s.transition_delay-(s.item_timer||0)))+'s remaining';$('media-progress-fill').style.width=s.is_video?'0%':Math.max(0,Math.min(100,100*(s.item_timer||0)/Math.max(1,s.transition_delay)))+'%';
  $('playback-state').textContent=s.screen_blanked?'Screen off':s.paused?'Paused':'Playing';$('lbl-shuffle').textContent=s.shuffle?'on':'off';$('btn-shuffle').setAttribute('aria-pressed',String(s.shuffle));$('lbl-screen').textContent=s.screen_blanked?'off':'on';$('btn-screen').setAttribute('aria-pressed',String(!s.screen_blanked));$('icon-pause').textContent=s.paused?'▷':'Ⅱ';$('txt-pause').textContent=s.paused?'Resume':'Pause';$('btn-pause').setAttribute('aria-label',s.paused?'Resume slideshow':'Pause slideshow');
  for(const [id,key] of Object.entries({'stat-uptime':'uptime','stat-temp':'temp','stat-mem':'mem','stat-disk':'disk','stat-db':'db_size','stat-queue':'total'}))$(id).textContent=s[key];$('stat-mqtt-status').textContent=s.mqtt_status==='enabled'?'enabled':'disabled';$('stat-mqtt-broker').textContent=s.mqtt_status==='enabled'?s.mqtt_broker+':'+s.mqtt_port:'';
 }catch{FrameUI.connection(false);$('device-state').textContent='Offline';}finally{statusBusy=false;}}
 async function command(path,button){if(button.disabled)return;button.disabled=true;try{error('');await request(path);setTimeout(fetchStatus,250);}catch(e){error(e.message);}finally{setTimeout(()=>button.disabled=false,650);}}
 for(const [id,path] of Object.entries({'btn-prev':'/api/prev','btn-next':'/api/next','btn-pause':'/api/pause','btn-shuffle':'/api/toggle_shuffle','btn-screen':'/api/toggle_screen'}))$(id).addEventListener('click',()=>command(path,$(id)));
 $('restart-frame').addEventListener('click',()=>{if(confirm('Restart piTrove? Playback will resume automatically.')){command('/api/restart',$('restart-frame'));toast('Restarting the frame…');}});
 $('refresh-preview').addEventListener('click',refreshPreview);$('capture-frame').addEventListener('click',async()=>{const b=$('capture-frame');b.disabled=true;try{error('');const blob=await request('/api/screenshot',{blob:true,timeout:15000});FrameUI.download(blob,'pitrove-frame-'+new Date().toISOString().replace(/[:.]/g,'-')+'.png');toast('Frame image ready to save.');}catch(e){error(e.message);}finally{setTimeout(()=>b.disabled=false,2200);}});
 async function summary(){if(summaryBusy||document.hidden)return;summaryBusy=true;lastSummary=Date.now();try{const data=await request('/api/chores'),due=data.chores.filter(c=>c.due),done=due.filter(c=>c.completed).length,remaining=due.length-done;const number=document.createTextNode(String(remaining)),label=document.createElement('span');label.textContent=' chore'+(remaining===1?'':'s')+' to go';$('chore-summary-number').replaceChildren(number,label);$('chore-summary-progress').max=Math.max(1,due.length);$('chore-summary-progress').value=done;$('chore-summary-text').textContent=!data.people.length?'Add your people and give the household a little rhythm.':!due.length?'A clear board today. Add a chore whenever you need one.':remaining===0?'Everything checked off. Enjoy the rest of your day.':done+' of '+due.length+' completed · shared by '+data.people.length+' '+(data.people.length===1?'person':'people')+'.';}catch(e){$('chore-summary-number').textContent='—';$('chore-summary-text').textContent=e.status===401?'Unlock the controller to see your household.':'The chore board is temporarily unavailable.';}finally{summaryBusy=false;}}
 function renderLogs(){const query=$('log-search').value.toLowerCase(),all=logs.split('\n'),filtered=all.filter(line=>!query||line.toLowerCase().includes(query));$('log-console').textContent=filtered.join('\n')||'No matching log lines.';$('log-lines').textContent=filtered.filter(Boolean).length+' matching lines';if($('follow-logs').checked)$('log-console').scrollTop=$('log-console').scrollHeight;}
 async function fetchLogs(){if(logBusy||document.hidden||currentTab!=='logs')return;logBusy=true;try{const data=await request('/api/logs');logs=data.logs||'';renderLogs();$('log-error').hidden=true;$('log-updated').textContent='Updated '+new Date().toLocaleTimeString();}catch(e){$('log-error').textContent=e.message;$('log-error').hidden=false;}finally{logBusy=false;}}
 $('log-search').addEventListener('input',renderLogs);$('follow-logs').addEventListener('change',renderLogs);$('refresh-logs').addEventListener('click',fetchLogs);$('live-logs').addEventListener('change',()=>{if($('live-logs').checked)fetchLogs();});$('download-logs').addEventListener('click',()=>FrameUI.download(new Blob([logs],{type:'text/plain;charset=utf-8'}),'pitrove-logs.txt'));
 $('lan-address').value=location.origin+'/';$('lan-protocol').textContent=location.protocol+'//';$('lan-address').addEventListener('click',()=>$('lan-address').select());$('copy-address').addEventListener('click',async()=>{try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText($('lan-address').value);else {$('lan-address').select();if(!document.execCommand('copy'))throw Error();}toast('LAN address copied.');}catch{$('lan-address').focus();$('lan-address').select();toast('Select and copy the highlighted address.');}});
 document.addEventListener('keydown',e=>{if(currentTab!=='remote'||e.altKey||e.ctrlKey||e.metaKey||e.repeat||e.target.closest('input,select,textarea,button,a,[contenteditable=true]'))return;const button=e.code==='Space'?'btn-pause':e.code==='ArrowRight'?'btn-next':e.code==='ArrowLeft'?'btn-prev':null;if(button){e.preventDefault();$(button).click();}});
 window.addEventListener('hashchange',switchTab);document.addEventListener('visibilitychange',()=>{if(!document.hidden){fetchStatus();if(currentTab==='logs')fetchLogs();if(Date.now()-lastSummary>30000)summary();}});FrameUI.onUnlock(async()=>{summary();if(currentTab==='logs')fetchLogs();});switchTab();summary();
 async function poll(){await fetchStatus();if(currentTab==='logs'&&$('live-logs').checked)await fetchLogs();if(Date.now()-lastSummary>30000)summary();setTimeout(poll,currentTab==='remote'?2000:5000);}setTimeout(poll,2000);
})();
</script>
)DASHBOARD"+webui::end(version);
}
